55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const BLOCK_SIZE = 3;
69	
70	const BLOCK_BASE_PREMIUM = 60;
71	
72	const countsByType = (items: Item[]): Map<string, number> => {
73	  const counts = new Map<string, number>();
74	
75	  for (const item of items) {
76	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
77	  }
78	
79	  return counts;
80	};
81	
82	const basePremiumFor = (type: string, count: number): number =>
83	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
84	
85	const policyBaseOf = (items: Item[]): number => {
86	  let total = 0;
87	
88	  for (const [type, count] of countsByType(items)) {
89	    total += basePremiumFor(type, count);
90	  }
91	
92	  return total;
93	};
94	
95	// Keep this as `base + base * RATE`. The algebraically equivalent
96	// `base * (1 + RATE)` is NOT safe here: 100 * 1.1 === 110.00000000000001 in
97	// IEEE-754, and Math.ceil turns that into 116 instead of 115. Ceil amplifies
98	// upward float error rather than absorbing it.
99	const quote = (items: Item[]): QuoteResult => {
100	  const policyBase = policyBaseOf(items);
101	
102	  return {
103	    premium: Math.ceil(
104	      policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE,
105	    ),
106	  };
107	};
108	
109	const runStep = (step: Step): StepResult => {
110	  if (step.op === "quote") return quote(step.items);
111	
112	  throw new Error(`Unsupported step: ${step.op}`);
113	};
114	
115	export const runScenario = (scenario: Scenario): ScenarioResult => ({
116	  results: scenario.steps.map(runStep),
117	});
